  updatedAt: string;
  entryCount: number;
}

export interface ConversationSummary {
  sessionId: string;
  createdAt: string;
  updatedAt: string;
  entryCount: number;
}

export type IncomingMessage = UserMessagePayload | PingMessage | ListSessionsMessage | ListConversationsMessage;

export interface ConnectedMessage {
  type: 'connected';
  sessionId: string;
  message: string;
  examplePrompts: string[];
  resumed?: boolean;
  entryCount?: number;
  /** Why a named id was not rejoined: `expired` only for the session's own owner, `unknown` for every other case. */
  resumeFailure?: 'expired' | 'unknown';
}

export interface EntryUpsertMessage {
  type: 'entry_upsert';
  index: number;
  entry: SessionEntry;
}

export interface EntryDeltaMessage {
  type: 'entry_delta';
  index: number;
  delta: string;
}

export interface EntryCommitMessage {
  type: 'entry_commit';
  index: number;
}

export interface ErrorMessage {
  type: 'error';
  code: string;
  message: string;
}

export interface PongMessage {
  type: 'pong';
  timestamp: number;
}

export interface EntrySkipMessage {
  type: 'entry_skip';
  index: number;
}

export interface StreamEndMessage {
  type: 'stream_end';
}

export interface SessionListMessage {
  type: 'session_list';
  sessions: SessionSummaryFrame[];
}

export interface ConversationListMessage {
  type: 'conversation_list';
  conversations: ConversationSummary[];
}

export type OutgoingMessage =
  | ConnectedMessage
  | EntryUpsertMessage
  | EntryDeltaMessage
  | EntryCommitMessage
  | EntrySkipMessage
  | ErrorMessage
  | PongMessage
  | StreamEndMessage
  | SessionListMessage
  | ConversationListMessage;

export {ErrorCodes} from './session.js';
import type {ConversationCursor, IncomingMessage} from '../../types/messages.js';
import type {SessionCursor} from '../../types/sessionStore.js';

const MAX_CONTENT_LENGTH = 10000;
const MAX_SESSION_ID_LENGTH = 128;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

type Validator = (message: Record<string, unknown>) => ValidationResult;

const validators = new Map<string, Validator>([
  ['user_message', validateUserMessage],
  ['ping', validatePingMessage],
  ['list_sessions', validateListSessionsMessage],
  ['list_conversations', validateListConversationsMessage],
]);

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = validators.get(message.type);
  return validator ? validator(message) : {valid: false, error: `Unknown message type: ${message.type}`};
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  if (!isValidListLimit(message.limit)) {
    return {valid: false, error: 'list_sessions limit must be an integer from 1 to 200'};
  }

  const before = validateSessionCursor(message.before);
  if (message.before !== undefined && before === undefined) {
    return {valid: false, error: 'list_sessions before must have a valid updatedAt and sessionId'};
  }

  return {
    valid: true,
    data: {
      type: 'list_sessions',
      limit: message.limit as number | undefined,
      before,
    },
  };
}

function isValidListLimit(value: unknown): value is number | undefined {
  if (value === undefined) return true;
  if (typeof value !== 'number') return false;
  if (!Number.isInteger(value)) return false;
  return value >= 1 && value <= 200;
}

function validateListConversationsMessage(message: Record<string, unknown>): ValidationResult {
  if (!isValidListLimit(message.limit)) {
    return {valid: false, error: 'list_conversations limit must be an integer from 1 to 200'};
  }

  const before = validateConversationCursor(message.before);
  if (message.before !== undefined && before === undefined) {
    return {valid: false, error: 'list_conversations before must have a valid updatedAt and sessionId'};
  }

  return {
    valid: true,
    data: {
      type: 'list_conversations',
      limit: message.limit as number | undefined,
      before,
    },
  };
}

function validateSessionCursor(value: unknown): SessionCursor | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== 'object' || value === null) return undefined;

  const cursor = value as Record<string, unknown>;
  const sessionId = cursor.sessionId;
  const updatedAt = cursor.updatedAt;
  if (!isValidSessionId(sessionId) || !isValidUpdatedAt(updatedAt)) return undefined;
  return {updatedAt: updatedAt as string | number, sessionId};
}

function isValidSessionId(value: unknown): value is string {
  return typeof value === 'string' && value.length >= 1 && value.length <= MAX_SESSION_ID_LENGTH;
}

function isValidUpdatedAt(value: unknown): value is string | number {
  if (typeof value === 'string') return Number.isFinite(Date.parse(value));
  return typeof value === 'number' && Number.isFinite(value);
}

function validateConversationCursor(value: unknown): ConversationCursor | undefined {
  if (value === undefined) return undefined;
  if (typeof value !== 'object' || value === null) return undefined;

  const cursor = value as Record<string, unknown>;
  if (
    !isValidSessionId(cursor.sessionId) ||
    typeof cursor.updatedAt !== 'string' ||
    !Number.isFinite(Date.parse(cursor.updatedAt))
  ) {
    return undefined;
  }
  return {updatedAt: cursor.updatedAt, sessionId: cursor.sessionId};
}
