import {serializeSessionSummary} from './sessionListSerialization.js';

describe('session list wire summaries', () => {
  it('serialises both summary dates as ISO strings', () => {
    expect(
      serializeSessionSummary({
        sessionId: 's1',
        createdAt: new Date('2026-01-01T00:00:00.000Z'),
        updatedAt: new Date('2026-01-02T00:00:00.000Z'),
        entryCount: 2,
      })
    ).toEqual({
      sessionId: 's1',
      createdAt: '2026-01-01T00:00:00.000Z',
